export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
    id: string;
    title: string;
    description: string;
    status: TaskStatus;
    assigneeId: string | null;
    projectId: string;
}

const STATUS_ORDER: TaskStatus[] = ['todo', 'in-progress', 'done'];

export class TaskService {
    private tasks: Map<string, Task> = new Map();

    constructor(private eventBus: EventBus) {}

    // Create
    create(data: { title: string; description: string; projectId: string }): Task {
        const id = crypto.randomUUID();
        const task: Task = {
            id,
            ...data,
            status: 'todo',
            assigneeId: null,
        };
        this.tasks.set(id, task);
        return task;
    }

    // Get by ID
    getById(id: string): Task | undefined {
        return this.tasks.get(id);
    }

    // Get by Project
    getByProject(projectId: string): Task[] {
        return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
    }

    // Update (general purpose)
    update(id: string, data: Partial<Omit<Task, 'id' | 'status' | 'assigneeId' | 'projectId'>>): Task | undefined {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }
        const updatedTask = { ...task, ...data };
        this.tasks.set(id, updatedTask);
        return updatedTask;
    }

    // Delete
    delete(id: string): boolean {
        return this.tasks.delete(id);
    }

    // Assign
    assign(id: string, assigneeId: string): Task | undefined {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }
        task.assigneeId = assigneeId;

        this.eventBus.publish('task.assigned', {
            taskId: task.id,
            taskTitle: task.title,
            assigneeId: task.assigneeId,
        });

        return task;
    }

    // Change Status
    changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }

        const oldStatus = task.status;
        const oldIndex = STATUS_ORDER.indexOf(oldStatus);
        const newIndex = STATUS_ORDER.indexOf(newStatus);

        if (newIndex < oldIndex) {
            // Disallow backward transitions
            return undefined;
        }

        task.status = newStatus;

        if (task.assigneeId) {
            this.eventBus.publish('task.statusChanged', {
                taskId: task.id,
                taskTitle: task.title,
                assigneeId: task.assigneeId,
                oldStatus,
                newStatus,
            });
        }

        return task;
    }
}

import crypto from 'crypto';
import { EventBus } from '../event-bus';

export interface Comment {
    id: string;
    taskId: string;
    authorId: string;
    body: string;
    createdAt: Date;
}

// Extra data needed for publishing the event, passed in by the router.
interface CommentEventData {
    taskTitle: string;
    authorName: string;
    taskAssigneeId: string | null;
}

export class CommentService {
    private comments: Map<string, Comment> = new Map();

    constructor(private eventBus: EventBus) {}

    // Create
    create(data: { taskId: string; authorId: string; body: string; }, eventData: CommentEventData): Comment {
        const id = crypto.randomUUID();
        const comment: Comment = {
            id,
            ...data,
            createdAt: new Date(),
        };
        this.comments.set(id, comment);

        // Publish event only if there is an assignee to notify
        if (eventData.taskAssigneeId) {
            this.eventBus.publish('comment.added', {
                commentId: comment.id,
                taskId: comment.taskId,
                authorId: comment.authorId,
                taskTitle: eventData.taskTitle,
                authorName: eventData.authorName,
                // Pass this along so the notification service knows who to notify
                taskAssigneeId: eventData.taskAssigneeId,
            });
        }

        return comment;
    }

    // Get by ID
    getById(id: string): Comment | undefined {
        return this.comments.get(id);
    }

    // Get by Task
    getByTask(taskId: string): Comment[] {
        return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
    }

    // Delete
    delete(id: string): boolean {
        return this.comments.delete(id);
    }
}

import crypto from 'crypto';
import { EventBus } from '../event-bus';

export interface Notification {
    id: string;
    userId: string;
    message: string;
    read: boolean;
    createdAt: Date;
}

export class NotificationService {
    private notifications: Map<string, Notification> = new Map();

    constructor(private eventBus: EventBus) {
        this.eventBus.subscribe('task.assigned', this.handleTaskAssigned.bind(this));
        this.eventBus.subscribe('task.statusChanged', this.handleTaskStatusChanged.bind(this));
        this.eventBus.subscribe('comment.added', this.handleCommentAdded.bind(this));
    }

    private createNotification(userId: string, message: string): Notification {
        const id = crypto.randomUUID();
        const notification: Notification = {
            id,
            userId,
            message,
            read: false,
            createdAt: new Date(),
        };
        this.notifications.set(id, notification);
        return notification;
    }

    private handleTaskAssigned(payload: { taskId: string; taskTitle: string; assigneeId: string; }): void {
        const { taskTitle, assigneeId } = payload;
        const message = `You have been assigned to task: "${taskTitle}"`;
        this.createNotification(assigneeId, message);
    }

    private handleTaskStatusChanged(payload: { taskId: string; taskTitle: string; assigneeId: string; oldStatus: string; newStatus: string; }): void {
        const { taskTitle, assigneeId, oldStatus, newStatus } = payload;
        const message = `The status of your task "${taskTitle}" has changed from ${oldStatus} to ${newStatus}.`;
        this.createNotification(assigneeId, message);
    }

    private handleCommentAdded(payload: { commentId: string; taskId: string; taskTitle: string; authorName: string; taskAssigneeId: string; }): void {
        const { taskTitle, authorName, taskAssigneeId } = payload;
        // A user should not be notified of their own comments.
        // The event payload has authorId, but the handler only gets a subset.
        // This logic should be handled by the publisher or the event data.
        // For now, we assume the user to notify is the taskAssigneeId and it's not the author.
        const message = `New comment from ${authorName} on your task "${taskTitle}"`;
        this.createNotification(taskAssigneeId, message);
    }

    // Get by User
    getByUser(userId: string): Notification[] {
        return Array.from(this.notifications.values())
            .filter(n => n.userId === userId)
            .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
    }

    // Mark as Read
    markAsRead(id: string): Notification | undefined {
        const notification = this.notifications.get(id);
        if (notification) {
            notification.read = true;
        }
        return notification;
    }
}

import * as http from 'http';
import * as url from 'url';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService, TaskStatus } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

export class Router {
    constructor(
        private userService: UserService,
        private projectService: ProjectService,
        private taskService: TaskService,
        private commentService: CommentService,
        private notificationService: NotificationService
    ) {}

    public async handleRequest(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
        const { pathname, query } = url.parse(req.url || '', true);
        const method = req.method;

        res.setHeader('Content-Type', 'application/json');

        try {
            // User routes
            if (pathname === '/users') {
                if (method === 'GET') {
                    const users = this.userService.getAll();
                    this.sendResponse(res, 200, users);
                } else if (method === 'POST') {
                    const body = await this.parseBody(req);
                    const newUser = this.userService.create(body);
                    this.sendResponse(res, 201, newUser);
                }
            } else if (pathname?.match(/^\/users\/([a-zA-Z0-9-]+)$/)) {
                const id = pathname.split('/')[2];
                if (method === 'GET') {
                    const user = this.userService.getById(id);
                    if (user) this.sendResponse(res, 200, user);
                    else this.sendResponse(res, 404, { message: 'User not found' });
                } else if (method === 'PUT') {
                    const body = await this.parseBody(req);
                    const updatedUser = this.userService.update(id, body);
                    if (updatedUser) this.sendResponse(res, 200, updatedUser);
                    else this.sendResponse(res, 404, { message: 'User not found' });
                } else if (method === 'DELETE') {
                    if (this.userService.delete(id)) this.sendResponse(res, 204);
                    else this.sendResponse(res, 404, { message: 'User not found' });
                }
            }

            // Project routes
            else if (pathname === '/projects') {
                if (method === 'GET') {
                    this.sendResponse(res, 200, this.projectService.getAll());
                } else if (method === 'POST') {
                    const body = await this.parseBody(req);
                    const newProject = this.projectService.create(body);
                    this.sendResponse(res, 201, newProject);
                }
            } else if (pathname?.match(/^\/projects\/([a-zA-Z0-9-]+)$/)) {
                const id = pathname.split('/')[2];
                if (method === 'GET') {
                    const project = this.projectService.getById(id);
                    if (project) this.sendResponse(res, 200, project);
                    else this.sendResponse(res, 404, { message: 'Project not found' });
                } else if (method === 'PUT') {
                    const body = await this.parseBody(req);
                    const updatedProject = this.projectService.update(id, body);
                    if (updatedProject) this.sendResponse(res, 200, updatedProject);
                    else this.sendResponse(res, 404, { message: 'Project not found' });
                } else if (method === 'DELETE') {
                    if (this.projectService.delete(id)) this.sendResponse(res, 204);
                    else this.sendResponse(res, 404, { message: 'Project not found' });
                }
            } else if (pathname?.match(/^\/projects\/([a-zA-Z0-9-]+)\/members$/)) {
                const id = pathname.split('/')[2];
                const body = await this.parseBody(req);
                if (method === 'POST') {
                    const project = this.projectService.addMember(id, body.memberId);
                    if (project) this.sendResponse(res, 200, project);
                    else this.sendResponse(res, 404, { message: 'Project not found' });
                } else if (method === 'DELETE') {
                    const project = this.projectService.removeMember(id, body.memberId);
                    if (project) this.sendResponse(res, 200, project);
                    else this.sendResponse(res, 404, { message: 'Project not found' });
                }
            }

            // Task routes
            else if (pathname === '/tasks') {
                if (method === 'GET' && query.projectId) {
                    this.sendResponse(res, 200, this.taskService.getByProject(query.projectId as string));
                } else if (method === 'POST') {
                    const body = await this.parseBody(req);
                    const newTask = this.taskService.create(body);
                    this.sendResponse(res, 201, newTask);
                }
            } else if (pathname?.match(/^\/tasks\/([a-zA-Z0-9-]+)$/)) {
                const id = pathname.split('/')[2];
                 if (method === 'GET') {
                    const task = this.taskService.getById(id);
                    if (task) this.sendResponse(res, 200, task);
                    else this.sendResponse(res, 404, { message: 'Task not found' });
                } else if (method === 'PUT') {
                    const body = await this.parseBody(req);
                    const updatedTask = this.taskService.update(id, body);
                    if (updatedTask) this.sendResponse(res, 200, updatedTask);
                     else this.sendResponse(res, 404, { message: 'Task not found' });
                } else if (method === 'DELETE') {
                    if (this.taskService.delete(id)) this.sendResponse(res, 204);
                    else this.sendResponse(res, 404, { message: 'Task not found' });
                }
            } else if (pathname?.match(/^\/tasks\/([a-zA-Z0-9-]+)\/status$/)) {
                const id = pathname.split('/')[2];
                if (method === 'PUT') {
                    const body = await this.parseBody(req);
                    const updatedTask = this.taskService.changeStatus(id, body.status as TaskStatus);
                    if (updatedTask) this.sendResponse(res, 200, updatedTask);
                    else this.sendResponse(res, 400, { message: 'Invalid status transition or task not found' });
                }
            } else if (pathname?.match(/^\/tasks\/([a-zA-Z0-9-]+)\/assign$/)) {
                 const id = pathname.split('/')[2];
                if (method === 'PUT') {
                    const body = await this.parseBody(req);
                    const updatedTask = this.taskService.assign(id, body.assigneeId);
                    if (updatedTask) this.sendResponse(res, 200, updatedTask);
                    else this.sendResponse(res, 404, { message: 'Task not found' });
                }
            }

            // Comment routes
            else if (pathname === '/comments') {
                if (method === 'GET' && query.taskId) {
                    this.sendResponse(res, 200, this.commentService.getByTask(query.taskId as string));
                } else if (method === 'POST') {
                    const body = await this.parseBody(req);
                    const { taskId, authorId } = body;
                    const task = this.taskService.getById(taskId);
                    const author = this.userService.getById(authorId);

                    if (!task || !author) {
                        this.sendResponse(res, 404, { message: 'Task or Author not found' });
                        return;
                    }

                    const newComment = this.commentService.create(body, {
                        taskTitle: task.title,
                        authorName: author.name,
                        taskAssigneeId: task.assigneeId
                    });
                    this.sendResponse(res, 201, newComment);
                }
            } else if (pathname?.match(/^\/comments\/([a-zA-Z0-9-]+)$/)) {
                const id = pathname.split('/')[2];
                if (method === 'GET') {
                    const comment = this.commentService.getById(id);
                    if (comment) this.sendResponse(res, 200, comment);
                    else this.sendResponse(res, 404, { message: 'Comment not found' });
                } else if (method === 'DELETE') {
                    if (this.commentService.delete(id)) this.sendResponse(res, 204);
                    else this.sendResponse(res, 404, { message: 'Comment not found' });
                }
            }

            // Notification routes
            else if (pathname === '/notifications' && query.userId) {
                if (method === 'GET') {
                    this.sendResponse(res, 200, this.notificationService.getByUser(query.userId as string));
                }
            } else if (pathname?.match(/^\/notifications\/([a-zA-Z0-9-]+)\/read$/)) {
                const id = pathname.split('/')[2];
                if (method === 'PUT') {
                    const notification = this.notificationService.markAsRead(id);
                    if (notification) this.sendResponse(res, 200, notification);
                    else this.sendResponse(res, 404, { message: 'Notification not found' });
                }
            }

            // Fallback for unhandled routes
            else {
                this.sendResponse(res, 404, { message: 'Not Found' });
            }
        } catch (error) {
            console.error('Internal Server Error:', error);
            this.sendResponse(res, 500, { message: 'Internal Server Error' });
        }
    }

    private parseBody(req: http.IncomingMessage): Promise<any> {
        return new Promise((resolve, reject) => {
            let body = '';
            req.on('data', chunk => body += chunk.toString());
            req.on('end', () => {
                try {
                    resolve(JSON.parse(body || '{}'));
                } catch (e) {
                    reject(e);
                }
            });
            req.on('error', reject);
        });
    }

    private sendResponse(res: http.ServerResponse, statusCode: number, data?: any): void {
        res.statusCode = statusCode;
        if (data) {
            res.end(JSON.stringify(data));
        } else {
            res.end();
        }
    }
}

import * as http from 'http';
import { EventBus, eventBus } from './event-bus';
